import json
from src.nodes.base import BaseNode
from src.runtime.reality import get_functional_zone_builder

_EMPTY = {"zones_json": "[]", "orphans_json": "[]", "no_orphans": False,
          "zone_count": 0, "exec_out": True}

class Hou_Mcp_Functional_Zones(BaseNode):
    name = "hou_mcp_functional_zones"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("scene_layout_json", "string", widget_type="text", default="{}")
        self.add_output("zones_json")
        self.add_output("orphans_json")
        self.add_output("no_orphans", "bool")
        self.add_output("zone_count", "int")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        try:
            scene = json.loads((inputs.get("scene_layout_json") or "{}").strip() or "{}")
        except Exception:
            self.log_error("scene_layout_json is not valid JSON.")
            return dict(_EMPTY)
        try:
            plan = get_functional_zone_builder().build_zones(scene)
            for f in plan.findings:
                self.log_error(f)
            return {
                "zones_json": json.dumps([z.to_dict() for z in plan.zones], sort_keys=True, indent=2),
                "orphans_json": json.dumps(plan.orphans, sort_keys=True, indent=2),
                "no_orphans": plan.no_orphans,
                "zone_count": len(plan.zones),
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Functional zone build failed: {exc}")
            return dict(_EMPTY)

def register_node():
    return Hou_Mcp_Functional_Zones
